index 22cb77b..b774ab3 100644
--- a/src/limiter.ts
+++ b/src/limiter.ts
@@ -6,3 +6,22 @@ const WINDOW_MS = 60_000;

 export const allow = (counter: Counter, key: string, limit: number, now: number): boolean =>
   counter.increment(key, WINDOW_MS, now) <= limit;
+
+interface Window {
+  count: number;
+  resetAt: number;
+}
+
+type Store = Map<string, Window>;
+
+export const createStoreCounter = (store: Store): Counter => ({
+  increment: (key: string, windowMs: number, now: number): number => {
+    const window = store.get(key);
+    if (window === undefined || window.resetAt <= now) {
+      store.set(key, { count: 1, resetAt: now + windowMs });
+      return 1;
+    }
+    window.count += 1;
+    return window.count;
+  },
+});
